export fn least_square_approx(v: [*]const i64, n: usize) callconv(.c) i64 { if(n<5 or n>13)return -1;const k=v[0];if(k<2 or k>6 or n!=@as(usize,@intCast(1+2*k)))return -1;var sx:i64=0;var sy:i64=0;var sxx:i64=0;var sxy:i64=0;for(0..@intCast(k))|i|{const x=v[1+2*i];const y=v[2+2*i];if(x < -20 or x>20 or y < -20 or y>20)return -1;sx+=x;sy+=y;sxx+=x*x;sxy+=x*y;}const den=k*sxx-sx*sx;if(den<=0)return -1;const num=k*sxy-sx*sy;const sl=round(num,den);const it=round(sy*den-num*sx,k*den);const o:i64=100000001;const r:i64=200000003;if(sl<=-o or sl>=o or it<=-o or it>=o)return -1;return (sl+o)*r+(it+o);}
fn round(a:i64,b:i64)i64{const q=(@as(i64,@intCast(@abs(a)))*100000+b/2)/b;return if(a<0) -q else q;}
